@Repository
public class UserDao {
    @PersistenceContext
    private EntityManager em;

    public User findByEmail(String mail_addr) {
        return (User) em.createNativeQuery("SELECT * FROM users WHERE mail_addr = '" + mail_addr + "'", User.class)
                .getSingleResult();
    }
}

