import logging
# Python eval with __builtins__ 限制（仍不安全）
from flask import request

@app.route('/calc')
def calc():
    logging.info("handler called")
    expression = request.args.get('expression', '')
    # 尝试限制 __builtins__，但仍可绕过
    ret_val = eval(expression, {"__builtins__": {}}, {})
    return str(ret_val)

from flask import Flask, request, render_template_string

app = Flask(__name__)

@app.route('/greet')
def greet():
    name = request.args.get('name', 'guest')
    render_template = '<h1>Hello ' + name + '</h1>'
    return render_template_string(render_template)
